mapper.select:
SELECT d.id,d.declaration_id AS declarationId,d.revision_no AS revision,d.execution_code AS executionCode,
  d.affected_node_id AS routingNodeId,d.defect_qty AS defectQty,d.record_action AS recordAction
FROM mes_production_defect d
WHERE d.id > #{afterId} AND NOT EXISTS (SELECT 1 FROM mes_production_defect newer
  WHERE newer.declaration_id=d.declaration_id AND newer.revision_no>d.revision_no)
AND d.execution_code IN #{id}
AND d.declaration_id=#{declarationId}
AND d.id IN #{id}
AND d.declaration_id IN #{id}
ORDER BY d.id LIMIT #{limit}


SELECT CASE WHEN EXISTS (
  SELECT 1 FROM mes_production_defect d
  WHERE d.execution_code=#{executionCode}
    AND (d.record_action IS NULL OR CAST(d.record_action AS BINARY(32))!=CAST(#{voided} AS BINARY(32)))
    AND NOT EXISTS (SELECT 1 FROM mes_production_defect newer
      WHERE newer.declaration_id=d.declaration_id AND newer.revision_no>d.revision_no)
) OR EXISTS (
  SELECT 1 FROM mes_quality_treatment t
  WHERE t.execution_code=#{executionCode}
    AND (t.action_type IS NULL OR CAST(t.action_type AS BINARY(32))!=CAST(#{assess} AS BINARY(32)))
) THEN TRUE ELSE FALSE END
